c1-87cd-9f27c939904f" :answer-field/type :answer-field.type/radio] [:db/add "206dc374-3684-50c1-87cd-9f27c939904f" :answer-field/choices "19f3bdab-e402-56bf-8271-904a0aa642cb"] [:db/add "206dc374-3684-50c1-87cd-9f27c939904f" :answer-field/choices "64e57532-f196-52c6-85e8-88aa5bf2347e"] [:db/add "206dc374-3684-50c1-87cd-9f27c939904f" :answer-field/choices "c9f97e0c-8d6c-5216-af9c-ee8b465923fe"] [:db/add "206dc374-3684-50c1-87cd-9f27c939904f" :answer-field/choices "041ecb02-4787-5321-ae84-e9e267c8dbc4"] [:db/add "206dc374-3684-50c1-87cd-9f27c939904f" :answer-field/choices "796aa240-9af7-5c80-b27c-5c19fd6b9eaa"] [:db/add "206dc374-3684-50c1-87cd-9f27c939904f" :answer-field/correct "64e57532-f196-52c6-85e8-88aa5bf2347e"] [:db/ensure "206dc374-3684-50c1-87cd-9f27c939904f" :answer-field/validate] [:db/add "61250297-8258-5e6f-a79a-e7e33037d824" :question/id #uuid "61250297-8258-5e6f-a79a-e7e33037d824"] [:db/add "61250297-8258-5e6f-a79a-e7e33037d824" :question/problem "The curve has equation $3 x^{2} + y^{2}=49$. The **tangent** line at $\left(4,-1\right)$ meets the $x$-axis at $P$. Find the coordinates of $P$."] [:db/add "61250297-8258-5e6f-a79a-e7e33037d824" :question/worked-solution "Treat $y$ as a function of $x$. Differentiate implicitly and collect the derivative terms:

$$
\begin{aligned}
6 x+\left(2 y\right)\frac{dy}{dx}&=0 \\
\left(2 y\right)\frac{dy}{dx}&=-\left(6 x\right) \\
\frac{dy}{dx}&=-\frac{6 x}{2 y}
\end{aligned}
$$

Evaluate the tangent slope at the given point:

$$
m_{\mathrm{t}}=-\frac{24}{-2}=12
$$

The tangent line uses $m=12$.

Use the given point and this slope:

$$
\begin{aligned}
y-\left(-1\right)&=12\left(x-\left(4\right)\right) \\
y&=12\left(x-\left(4\right)\right)+\left(-1\right)
\end{aligned}
$$

At the $x$-axis, $y=0$. Substitute and simplify:

$$
\begin{aligned}
0&=12\left(x-\left(4\right)\right)+\left(-1\right) \\
x-\left(4\right)&=-\frac{-1}{12} \\
x&=\frac{49}{12}
\end{aligned}
$$

Therefore $P=\left(\frac{49}{12},0\right)$."] [:db/add "61250297-8258-5e6f-a79a-e7e33037d824" :question/difficulty :question.difficulty/easy] [:db/add "61250297-8258-5e6f-a79a-e7e33037d824" :question/answer-fields "206dc374-3684-50c1-87cd-9f27c939904f"] [:db/ensure "61250297-8258-5e6f-a79a-e7e33037d824" :question/validate] [:db/add 17592186054847 :knowledge-point/questions "61250297-8258-5e6f-a79a-e7e33037d824"] [:db/add "13adde5d-86b0-5409-b9bc-410af7b50b77" :answer/id #uuid "13adde5d-86b0-5409-b9bc-410af7b50b77"] [:db/add "13adde5d-86b0-5409-b9bc-410af7b50b77" :answer/type :answer.type/math] [:db/add "13adde5d-86b0-5409-b9bc-410af7b50b77" :answer/value "\left(0,-3\right)"] [:db/ensure "13adde5d-86b0-5409-b9bc-410af7b50b77" :answer/validate] [:db/add "643a3d08-17fb-5442-b0ea-d100d7686525" :answer/id #uuid "643a3d08-17fb-5442-b0ea-d100d7686525"] [:db/add "643a3d08-17fb-5442-b0ea-d100d7686525" :answer/type :answer.type/math] [:db/add "643a3d08-17fb-5442-b0ea-d100d7686525" :answer/value "\left(0,- \frac{13}{4}\right)"] [:db/ensure "643a3d08-17fb-5442-b0ea-d100d7686525" :answer/validate] [:db/add "908549b3-9799-5bb9-ad25-4b6985780fa6" :answer/id #uuid "908549b3-9799-5bb9-ad25-4b6985780fa6"] [:db/add "908549b3-9799-5bb9-ad25-4b6985780fa6" :answer/type :answer.type/math] [:db/add "908549b3-9799-5bb9-ad25-4b6985780fa6" :answer/value "\left(0,-10\right)"] [:db/ensure "908549b3-9799-5bb9-ad25-4b6985780fa6" :answer/validate] [:db/add "8dca58c4-e985-5061-9a30-551d7205ab8c" :answer/id #uuid "8dca58c4-e985-5061-9a30-551d7205ab8c"] [:db/add "8dca58c4-e985-5061-9a30-551d7205ab8c" :answer/type :answer.type/math] [:db/add "8dca58c4-e985-5061-9a30-551d7205ab8c" :answer/value "\left(0,- \frac{11}{2}\right)"] [:db/ensure "8dca58c4-e985-5061-9a30-551d7205ab8c" :answer/validate] [:db/add "204c1878-f15a-52c8-b15c-8cf82e58f862" :answer/id #uuid "204c1878-f15a-52c8-b15c-8cf82e58f862"] [:db/add "204c1878-f15a-52c8-b15c-8cf82e58f862" :answer/type :answer.type/math] [:db/add "204c1878-f15a-52c8-b15c-8cf82e58f862" :answer/value "\left(0,\frac{7}{2}\right)"] [:db/ensure "204c1878-f15a-52c8-b15c-8cf82e58f862" :answer/validate] [:db/add "0c464e2a-b520-537c-bdb3-2b95009f2a6f" :answer-field/id #uuid "0c464e2a-b520-537c-bdb3-2b95009f2a6f"] [:db/add "0c464e2a-b520-537c-bdb3-2b95009f2a6f" :answer-field/key "selection"] [:db/add "0c464e2a-b520-537c-bdb3-2b95009f2a6f" :answer-field/type :answer-field.type/radio] [:db/add "0c464e2a-b520-537c-bdb3-2b95009f2a6f" :answer-field/choices "13adde5d-86b0-5409-b9bc-410af7b50b77"] [:db/add "0c464e2a-b520-537c-bdb3-2b95009f2a6f" :answer-field/choices "643a3d08-17fb-5442-b0ea-d100d7686525"] [:db/add "0c464e2a-b520-537c-bdb3-2b95009f2a6f" :answer-field/choices "908549b3-9799-5bb9-ad25-4b6985780fa6"] [:db/add "0c464e2a-b520-537c-bdb3-2b95009f2a6f" :answer-field/choices "8dca58c4-e985-5061-9a30-551d7205ab8c"] [:db/add "0c464e2a-b520-537c-bdb3-2b95009f2a6f" :answer-field/choices "204c1878-f15a-52c8-b15c-8cf82e58f862"] [:db/add "0c464e2a-b520-537c-bdb3-2b95009f2a6f" :answer-field/correct "8dca58c4-e985-5061-9a30-551d7205ab8c"] [:db/ensure "0c464e2a-b520-537c-bdb3-2b95009f2a6f" :answer-field/validate] [:db/add "d1475a99-31d5-5d3b-b827-4c42b1dd57db" :question/id #uuid "d1475a99-31d5-5d3b-b827-4c42b1dd57db"] [:db/add "d1475a99-31d5-5d3b-b827-4c42b1dd57db" :question/problem "The curve has equation $2 x^{2} + 4 y^{2}=22$. The **tangent** line at $\left(-3,-1\right)$ meets the $y$-axis at $P$. Find the coordinates of $P$."] [:db/add "d1475a99-31d5-5d3b-b827-4c42b1dd57db" :question/worked-solution "Treat $y$ as a function of $x$. Differentiate implicitly and collect the derivative terms:

$$
\begin{aligned}
4 x+\left(8 y\right)\frac{dy}{dx}&=0 \\
\left(8 y\right)\frac{dy}{dx}&=-\left(4 x\right) \\
\frac{dy}{dx}&=-\frac{4 x}{8 y}
\end{aligned}
$$

Evaluate the tangent slope at the given point:

$$
m_{\mathrm{t}}=-\frac{-12}{-8}=- \frac{3}{2}
$$

The tangent line uses $m=- \frac{3}{2}$.

Use the given point and this slope:

$$
\begin{aligned}
y-\left(-1\right)&=- \frac{3}{2}\left(x-\left(-3\right)\right) \\
y&=- \frac{3}{2}\left(x-\left(-3\right)\right)+\left(-1\right)
\end{aligned}
$$

At the $y$-axis, $x=0$. Substitute and simplify:

$$
\begin{aligned}
y&=- \frac{3}{2}\left(0-\left(-3\right)\right)+\left(-1\right) \\
y&=- \frac{11}{2}
\end{aligned}
$$

Therefore $P=\left(0,- \frac{11}{2}\right)$."] [:db/add "d1475a99-31d5-5d3b-b827-4c42b1dd57db" :question/difficulty :question.difficulty/easy] [:db/add "d1475a99-31d5-5d3b-b827-4c42b1dd57db" :question/answer-fields "0c464e2a-b520-537c-bdb3-2b95009f2a6f"] [:db/ensure "d1475a99-31d5-5d3b-b827-4c42b1dd57db" :question/validate] [:db/add 17592186054847 :knowledge-point/questions "d1475a99-31d5-5d3b-b827-4c42b1dd57db"] [:db/add "64ef6cbb-7907-576b-b4a0-775c19a5627b" :answer/id #uuid "64ef6cbb-7907-576b-b4a0-775c19a5627b"] [:db/add "64ef6cbb-7907-576b-b4a0-775c19a5627b" :answer/type :answer.type/math] [:db/add "64ef6cbb-7907-576b-b4a0-775c19a5627b" :answer/value "\left(- \frac{10}{3},0\right)"] [:db/ensure "64ef6cbb-7907-576b-b4a0-775c19a5627b" :answer/validate] [:db/add "d4ddede2-fcf0-5d1b-8694-8d07d3549a05" :answer/id #uuid "d4ddede2-fcf0-5d1b-8694-8d07d3549a05"] [:db/add "d4ddede2-fcf0-5d1b-8694-8d07d3549a05" :answer/type :answer.type/math] [:db/add "d4ddede2-fcf0-5d1b-8694-8d07d3549a05" :answer/value "\left(\frac{10}{3},0\right)"] [:db/ensure "d4ddede2-fcf0-5d1b-8694-8d07d3549a05" :answer/validate] [:db/add "fd253355-197c-54df-be47-2a3ae88b54e2" :answer/id #uuid "fd253355-197c-54df-be47-2a3ae88b54e2"] [:db/add "fd253355-197c-54df-be47-2a3ae88b54e2" :answer/type :answer.type/math] [:db/add "fd253355-197c-54df-be47-2a3ae88b54e2" :answer/value "\left(- \frac{14}{3},0\right)"] [:db/ensure "fd253355-197c-54df-be47-2a3ae88b54e2" :answer/validate] [:db/add "b965be5a-c6bd-5c86-92ac-a1982abeab2d" :answer/id #uuid "b965be5a-c6bd-5c86-92ac-a1982abeab2d"] [:db/add "b965be5a-c6bd-5c86-92ac-a1982abeab2d" :answer/type :answer.type/math] [:db/add "b965be5a-c6bd-5c86-92ac-a1982abeab2d" :answer/value "\left(- \frac{2}{3},0\right)"] [:db/ensure "b965be5a-c6bd-5c86-92ac-a1982abeab2d" :answer/validate] [:db/add "f5b7be49-cec9-5cbe-925e-07dbc421db84" :answer/id #uuid "f5b7be49-cec9-5cbe-925e-07dbc421db84"] [:db/add "f5b7be49-cec9-5cbe-925e-07dbc421db84" :answer/type :answer.type/math] [:db/add "f5b7be49-cec9-5cbe-925e-07dbc421db84" :answer/value "\left(- \frac{4}{3},0\right)"] [:db/ensure "f5b7be49-cec9-5cbe-925e-07dbc421db84" :answer/validate] [:db/add "f0f3c380-9e07-51a9-afcd-a21f64d3543e" :answer-field/id #uuid "f0f3c380-9e07-51a9-afcd-a21f64d3543e"] [:db/add "f0f3c380-9e07-51a9-afcd-a21f64d3543e" :answer-field/key "selection"] [:db/add "f0f3c380-9e07-51a9-afcd-a21f64d3543e" :answer-field/type :answer-field.type/radio] [:db/add "f0f3c380-9e07-51a9-afcd-a21f64d3543e" :answer-field/choices "64ef6cbb-7907-576b-b4a0-775c19a5627b"] [:db/add "f0f3c380-9e07-51a9-afcd-a21f64d3543e" :answer-field/choices "d4ddede2-fcf0-5d1b-8694-8d07d3549a05"] [:db/add "f0f3c380-9e07-51a9-afcd-a21f64d3543e" :answer-field/choices "fd253355-197c-54df-be47-2a3ae88b54e2"] [:db/add "f0f3c380-9e07-51a9-afcd-a21f64d3543e" :answer-field/choices "b965be5a-c6bd-5c86-92ac-a1982abeab2d"] [:db/add "f0f3c380-9e07-51a9-afcd-a21f64d3543e" :answer-field/choices "f5b7be49-cec9-5cbe-925e-07dbc421db84"] [:db/add "f0f3c380-9e07-51a9-afcd-a21f64d3543e" :answer-field/correct "64ef6cbb-7907-576b-b4a0-775c19a5627b"] [:db/ensure "f0f3c380-9e07-51a9-afcd-a21f64d3543e" :answer-field/validate] [:db/add "a4d5312c-4c3b-5396-9fe9-723b2ba4036b" :question/id #uuid "a4d5312c-4c3b-5396-9fe9-723b2ba4036b"] [:db/add "a4d5312c-4c3b-5396-9fe9-723b2ba4036b" :question/problem "The curve has equation $3 x^{2} + 2 y^{2}=20$. The **tangent** line at $\left(-2,-2\right)$ meets the $x$-axis at $P$. Find the coordinates of $P$."] [:db/add "a4d5312c-4c3b-5396-9fe9-723b2ba4036b" :question/worked-solution "Treat $y$ as a function of $x$. Differentiate implicitly and collect the derivative terms:

$$
\begin{aligned}
6 x+\left(4 y\right)\frac{dy}{dx}&=0 \\
\left(4 y\right)\frac{dy}{dx}&=-\left(6 x\right) \\
\frac{dy}{dx}&=-\frac{6 x}{4 y}
\end{aligned}
$$

Evaluate the tangent slope at the given point:

$$
m_{\mathrm{t}}=-\frac{-12}{-8}=- \frac{3}{2}
$$

The tangent line uses $m=- \frac{3}{2}$.

Use the given point and this slope:

$$
\begin{aligned}
y-\left(-2\right)&=- \frac{3}{2}\left(x-\left(-2\right)\right) \\
y&=- \frac{3}{2}\left(x-\left(-2\right)\right)+\left(-2\right)
\end{aligned}
$$

At the $x$-axis, $y=0$. Substitute and simplify:

$$
\begin{aligned}
0&=- \frac{3}{2}\left(x-\left(-2\right)\right)+\left(-2\right) \\
x-\left(-2\right)&=-\frac{-2}{- \frac{3}{2}} \\
x&=- \frac{10}{3}
\end{aligned}
$$

Therefore $P=\left(- \frac{10}{3},0\right)$."] [:db/add "a4d5312c-4c3b-5396-9fe9-723b2ba4036b" :question/difficulty :question.difficulty/easy] [:db/add "a4d5312c-4c3b-5396-9fe9-723b2ba4036b" :question/answer-fields "f0f3c380-9e07-51a9-afcd-a21f64d3543e"] [:db/ensure "a4d5312c-4c3b-5396-9fe9-723b2ba4036b" :question/validate] [:db/add 17592186054847 :knowledge-point/questions "a4d5312c-4c3b-5396-9fe9-723b2ba4036b"] [:db/add "1e9b38e2-8e31-54e0-8c7e-08d48bdd04fa" :answer/id #uuid "1e9b38e2-8e31-54e0-8c7e-08d48bdd04fa"] [:db/add "1e9b38e2-8e31-54e0-8c7e-08d48bdd04fa" :answer/type :answer.type/math] [:db/add "1e9b38e2-8e31-54e0-8c7e-08d48bdd04fa" :answer/value "\left(0,3\right)"] [:db/ensure "1e9b38e2-8e31-54e0-8c7e-08d48bdd04fa" :answer/validate] [:db/add "869da62c-50f0-5fb5-b267-7885b83decc2" :answer/id #uuid "869da62c-50f0-5fb5-b267-7885b83decc2"] [:db/add "869da62c-50f0-5fb5-b267-7885b83decc2" :answer/type :answer.type/math] [:db/add "869da62c-50f0-5fb5-b267-7885b83decc2" :answer/value "\left(0,7\right)"] [:db/ensure "869da62c-50f0-5fb5-b267-7885b83decc2" :answer/validate] [:db/add "0a508e0f-e064-561d-a86a-7e831952e1b3" :answer/id #uuid "0a508e0f-e064-561d-a86a-7e831952e1b3"] [:db/add "0a508e0f-e064-561d-a86a-7e831952e1b3" :answer/type :answer.type/math] [:db/add "0a508e0f-e064-561d-a86a-7e831952e1b3" :answer/value "\left(0,\frac{15}{2}\right)"] [:db/ensure "0a508e0f-e064-561d-a86a-7e831952e1b3" :answer/validate] [:db/add "e0386152-14b4-5cc9-a31a-84e95a337c6a" :answer/id #uuid "e0386152-14b4-5cc9-a31a-84e95a337c6a"] [:db/add "e0386152-14b4-5cc9-a31a-84e95a337c6a" :answer/type :answer.type/math] [:db/add "e0386152-14b4-5cc9-a31a-84e95a337c6a" :answer/value "\left(0,- \frac{3}{2}\right)"] [:db/ensure "e0386152-14b4-5cc9-a31a-84e95a337c6a" :answer/validate] [:db/add "382de773-b98c-59d6-8738-c8077238a5d0" :answer/id #uuid "382de773-b98c-59d6-8738-c8077238a5d0"] [:db/add "382de773-b98c-59d6-8738-c8077238a5d0" :answer/type :answer.type/math] [:db/add "382de773-b98c-59d6-87